async function getData(){const e=await fetch("/data/cover-letter.json");if(!e.ok)throw new Error("Error: "+e.status);return e.json()}function createItems(e){const n=document.createDocumentFragment();return e.forEach((function(e){const t=document.createElement("p");t.innerHTML=e,n.appendChild(t)})),n}function formatDate(e){return new Date(e).toLocaleDateString("en-US",{year:"numeric",month:"long",day:"numeric"})}window.addEventListener("DOMContentLoaded",(async function(){const e=document.querySelector("#cl-body"),n=document.querySelector("#date"),t=document.querySelector("#company"),o=document.querySelector("#manager"),r=new URLSearchParams(window.location.search).get("lang")||"en",{en:a,es:c}=await getData(),u="es"===r?c:a;o.addEventListener("input",(function(){document.querySelectorAll(".manager").forEach((function(e){e.innerText=o.innerText}))})),t.addEventListener("input",(function(){document.querySelectorAll(".company").forEach((function(e){e.innerText=t.innerText}))}));const i=createItems(u);e.appendChild(i);const d=formatDate(new Date);n.innerText=d}));
